/**
 * Creature Lab - Type Definitions
 * 
 * Core game types for body parts, creatures, combat, and player state.
 * 
 * FUTURE-PROOFING: This type system supports the full creature design:
 * - Torsos with up to 8 limbs (4 per side), wings, and shell
 * - Heads with horn, antennae, and gill attachment slots
 * - MVP only uses a subset of these slots
 */

// ================================
// Enums and Constants
// ================================

// Part types - includes future parts
export type PartType =
    | 'torso'
    | 'head'
    | 'arm'
    | 'leg'
    | 'tail'
    // Future part types
    | 'wing'
    | 'shell'
    | 'horn'
    | 'antennae'
    | 'gill';

export type AnimalType = 'rat' | 'squirrel' | 'cat' | 'dog' | 'skunk';
// Biomes - ordered by progression difficulty (defined in biomes.json)
export type Biome = 'city' | 'woods' | 'pond' | 'beach' | 'jungle';

// Note: EffectType is now defined in the Effect System section below (line ~91)

// All possible limb positions (future-proofed for 8 limbs)
export type LimbPosition = 1 | 2 | 3 | 4;
export type LimbSide = 'left' | 'right';

// Part slots - future-proofed for full creature
export type PartSlot =
    // Core (always present)
    | 'torso'
    | 'head'
    | 'tail'
    // MVP limbs (positions 1-2)
    | 'leftArm1' | 'rightArm1'   // Upper arms (MVP: leftArm, rightArm)
    | 'leftLeg1' | 'rightLeg1'   // Upper legs (MVP: leftLeg, rightLeg)
    // Future limbs (positions 2-4)
    | 'leftArm2' | 'rightArm2'
    | 'leftArm3' | 'rightArm3'
    | 'leftArm4' | 'rightArm4'
    | 'leftLeg2' | 'rightLeg2'
    | 'leftLeg3' | 'rightLeg3'
    | 'leftLeg4' | 'rightLeg4'
    // Future torso attachments
    | 'leftWing' | 'rightWing'
    | 'shell'
    // Future head attachments
    | 'leftHorn' | 'rightHorn'
    | 'leftAntenna' | 'rightAntenna'
    | 'leftGill' | 'rightGill';

// MVP-only slot type (what we currently use)
export type MVPPartSlot =
    | 'torso'
    | 'head'
    | 'leftArm1' | 'rightArm1'
    | 'leftLeg1' | 'rightLeg1'
    | 'tail';

// Legacy slot names for compatibility
export type LegacyPartSlot =
    | 'torso'
    | 'head'
    | 'leftArm' | 'rightArm'
    | 'leftLeg' | 'rightLeg'
    | 'tail';

// ================================
// Effect System
// ================================

// Comprehensive effect taxonomy (144 types across 12 categories)
export type EffectType =
    // 1. Direct Damage & Healing
    | 'damage' | 'heal' | 'true_damage' | 'lifesteal' | 'recoil' | 'execute' | 'overkill'
    | 'dot' | 'hot' | 'decay' | 'surge'
    // 2. AP Manipulation
    | 'buff_ap' | 'debuff_ap' | 'ap_steal' | 'ap_refund' | 'ap_lock' | 'ap_burst'
    | 'reduce_cost' | 'increase_cost' | 'free_attack' | 'double_cost'
    // 3. Initiative & Speed
    | 'buff_speed' | 'debuff_speed' | 'haste' | 'delay' | 'time_stop' | 'quicken'
    | 'extra_turn' | 'skip_turn' | 'swap_turns' | 'rewind'
    // 4. Defense & Mitigation
    | 'buff_defense' | 'debuff_defense' | 'shield' | 'barrier' | 'reflect' | 'thorns'
    | 'buff_evasion' | 'debuff_evasion' | 'parry' | 'counter' | 'phase' | 'invulnerable'
    // 5. Accuracy & Targeting
    | 'buff_accuracy' | 'debuff_accuracy' | 'guaranteed_hit' | 'guaranteed_miss'
    | 'buff_crit_chance' | 'buff_crit_damage' | 'guaranteed_crit' | 'crit_immunity'
    | 'cleave' | 'splash' | 'chain' | 'pierce'
    // 6. Status Conditions
    | 'stun' | 'freeze' | 'sleep' | 'charm' | 'confuse' | 'taunt'
    | 'poison' | 'bleed' | 'burn' | 'curse' | 'silence' | 'disarm'
    | 'disable_part' | 'cripple' | 'mute' | 'blind'
    // 7. Resource Manipulation
    | 'max_hp_buff' | 'max_hp_debuff' | 'hp_swap' | 'hp_link' | 'hp_drain'
    | 'transform' | 'mimic' | 'steal_part' | 'sacrifice'
    // 8. Combo & Synergy
    | 'on_hit' | 'on_miss' | 'on_crit' | 'on_kill' | 'on_damaged' | 'on_heal'
    | 'mark' | 'expose' | 'setup' | 'finisher' | 'combo_bonus' | 'element_react'
    // 9. Stacking & Duration
    | 'stack_decay' | 'stack_consume' | 'stack_transfer'
    | 'extend' | 'shorten' | 'permanent' | 'refresh' | 'cleanse' | 'purge'
    // 10. Conditional
    | 'low_hp_bonus' | 'high_hp_bonus' | 'desperation' | 'bloodlust'
    | 'first_turn' | 'last_turn' | 'odd_turns' | 'even_turns'
    | 'if_part_alive' | 'if_part_dead' | 'synergy' | 'anti_synergy'
    // 11. Unique Mechanics
    | 'evolve' | 'devolve' | 'mutate' | 'adapt'
    | 'gamble' | 'coin_flip' | 'dice_roll' | 'chaos'
    | 'hp_for_ap' | 'ap_for_hp' | 'hp_for_damage' | 'damage_for_heal'
    | 'swap_position' | 'push' | 'pull' | 'lock_position'
    // 12. Meta Effects
    | 'amplify' | 'dampen' | 'reverse' | 'copy_effect' | 'steal_effect' | 'redirect'
    | 'immune_dot' | 'immune_cc' | 'immune_debuff' | 'resist_all' | 'absorb_effect'
    | 'aura_damage' | 'aura_defense' | 'aura_speed' | 'aura_heal' | 'aura_debuff';

export type TriggerType =
    | 'instant'          // Happens immediately
    | 'on_hit'           // When attack lands
    | 'on_miss'          // When attack misses
    | 'on_crit'          // On critical hit
    | 'on_kill'          // When defeating opponent
    | 'on_damaged'       // When taking damage
    | 'on_heal'          // When healing
    | 'on_turn_start'    // Start of turn
    | 'on_turn_end'      // End of turn
    | 'on_part_destroyed'; // When part is destroyed

export type TargetType =
    | 'self'             // Caster
    | 'opponent'         // Enemy
    | 'all_self'         // All own parts
    | 'all_opponent'     // All enemy parts
    | 'random'           // Random target
    | 'specific_part';   // Specific part type

export type ScalingType =
    | 'flat'             // Fixed value
    | 'percent_hp'       // % of max HP
    | 'percent_missing'  // % of missing HP
    | 'per_stack'        // Multiplied by stacks
    | 'per_turn';        // Increases each turn

export interface Condition {
    targetHpBelow?: number;      // Target HP < X%
    targetHpAbove?: number;      // Target HP > X%
    selfHpBelow?: number;        // Self HP < X%
    selfHpAbove?: number;        // Self HP > X%
    hasEffect?: EffectType;      // Target has effect
    lacksEffect?: EffectType;    // Target lacks effect
    partAlive?: PartType;        // Specific part exists
    partDead?: PartType;         // Specific part destroyed
    turnNumber?: number;         // Specific turn
    oddTurn?: boolean;           // Odd turns only
    evenTurn?: boolean;          // Even turns only
}

export interface Effect {
    // Core properties
    type: EffectType;
    value: number;              // Magnitude (damage, healing, %, etc.)
    duration?: number;          // Turns (undefined = instant)

    // Stacking
    stacks?: boolean;           // Can stack?
    maxStacks?: number;         // Stack limit

    // Triggers & Conditions
    trigger?: TriggerType;      // When effect activates
    condition?: Condition;      // Requirement to activate

    // Targeting
    target?: TargetType;        // Who is affected
    partType?: PartType;        // Specific part type

    // Modifiers
    scaling?: ScalingType;      // How value scales
    chance?: number;            // Probability (0-100)

    // Combos
    requires?: EffectType[];    // Needs these effects present
    grants?: Effect[];          // Triggers additional effects
    consumes?: EffectType[];    // Removes these effects

    // Meta
    priority?: number;          // Execution order
    dispellable?: boolean;      // Can be cleansed?
    transferable?: boolean;     // Can be moved to other parts?
}

export interface ActiveEffect extends Effect {
    remainingDuration: number;
    sourceId?: string;          // Track source for stacking calculations
    currentStacks?: number;     // Current stack count
}


// ================================
// Attack System
// ================================

export interface AttackTutorial {
    bodyPart: string;
    headline: string;
    description: string;
}

export interface Attack {
    id?: string;            // Unique identifier from data file
    name: string;
    apCost: number;
    damage: number;
    effect: Effect | null;
    speed: number;          // Base speed for initiative (0-100, higher = faster)
    requiresBothLegs?: boolean;  // Cat's Pounce requires both legs
    description?: string;   // Human-readable description
    tutorial?: AttackTutorial;  // First-encounter tutorial data
}

export interface SelectedAttack {
    attack: Attack;
    sourcePartSlot: PartSlot;
    sourceAnimal: AnimalType;
}

// ================================
// Body Parts
// ================================

export interface BodyPartBase {
    partType: PartType;
    animalType: AnimalType;
    defense: number;
    attacks: Attack[];
}

export interface TorsoBodyPart extends BodyPartBase {
    partType: 'torso';
    hpBonus: number;
    // Future: maxLimbSlots?: number; // For octopus (8), spider (8), etc.
}

export interface HeadBodyPart extends BodyPartBase {
    partType: 'head';
    hpBonus: number;
    speedBonus: number;     // Initiative bonus applied to all attacks (0-20)
    // Future: hasHornSlots?: boolean;
    // Future: hasAntennaSlots?: boolean;
    // Future: hasGillSlots?: boolean;
}

export interface LimbBodyPart extends BodyPartBase {
    partType: 'arm' | 'leg' | 'tail';
    hpBonus?: never;  // Limbs don't have HP bonus
}

// Future attachment types
export interface WingBodyPart extends BodyPartBase {
    partType: 'wing';
    hpBonus?: never;
}

export interface ShellBodyPart extends BodyPartBase {
    partType: 'shell';
    hpBonus: number;  // Shell provides HP
}

export interface HeadAttachmentPart extends BodyPartBase {
    partType: 'horn' | 'antennae' | 'gill';
    hpBonus?: never;
}

export type BodyPart =
    | TorsoBodyPart
    | HeadBodyPart
    | LimbBodyPart
    | WingBodyPart
    | ShellBodyPart
    | HeadAttachmentPart;

// Helper type for data files
export interface BodyPartData {
    hpBonus?: number;
    defense: number;
    attacks: Attack[];
}

// ================================
// Creatures - Future-Proofed Layout
// ================================

/**
 * Full creature slots supporting 8 limbs + attachments
 * MVP only populates arm1, leg1 positions
 */
export interface CreatureSlots {
    // Core (permanent)
    torso: TorsoBodyPart;

    // Head + attachments
    head: HeadBodyPart | null;
    leftHorn: HeadAttachmentPart | null;     // Future
    rightHorn: HeadAttachmentPart | null;    // Future
    leftAntenna: HeadAttachmentPart | null;  // Future
    rightAntenna: HeadAttachmentPart | null; // Future
    leftGill: HeadAttachmentPart | null;     // Future
    rightGill: HeadAttachmentPart | null;    // Future

    // Arms (up to 4 per side)
    leftArm1: LimbBodyPart | null;   // MVP: main left arm
    rightArm1: LimbBodyPart | null;  // MVP: main right arm
    leftArm2: LimbBodyPart | null;   // Future
    rightArm2: LimbBodyPart | null;  // Future
    leftArm3: LimbBodyPart | null;   // Future
    rightArm3: LimbBodyPart | null;  // Future
    leftArm4: LimbBodyPart | null;   // Future
    rightArm4: LimbBodyPart | null;  // Future

    // Legs (up to 4 per side)
    leftLeg1: LimbBodyPart | null;   // MVP: main left leg
    rightLeg1: LimbBodyPart | null;  // MVP: main right leg
    leftLeg2: LimbBodyPart | null;   // Future
    rightLeg2: LimbBodyPart | null;  // Future
    leftLeg3: LimbBodyPart | null;   // Future
    rightLeg3: LimbBodyPart | null;  // Future
    leftLeg4: LimbBodyPart | null;   // Future
    rightLeg4: LimbBodyPart | null;  // Future

    // Tail
    tail: LimbBodyPart | null;

    // Back attachments
    leftWing: WingBodyPart | null;   // Future
    rightWing: WingBodyPart | null;  // Future
    shell: ShellBodyPart | null;     // Future
}

/**
 * MVP-only creature slots (what we display in Sprint 1)
 */
export interface MVPCreatureSlots {
    torso: TorsoBodyPart;
    head: HeadBodyPart | null;
    leftArm1: LimbBodyPart | null;
    rightArm1: LimbBodyPart | null;
    leftLeg1: LimbBodyPart | null;
    rightLeg1: LimbBodyPart | null;
    tail: LimbBodyPart | null;
}

export interface PlayerCreature {
    slots: CreatureSlots;
    // Computed values (calculated from parts)
    maxHp: number;
    currentHp: number;
    totalDefense: number;
    activeEffects: ActiveEffect[];
}

export interface WildCreature {
    type: AnimalType;
    biome: Biome;
    totalHp: number;
    currentHp: number;
    defense: number;
    apPerTurn: number;
    attacks: Attack[];
    activeEffects: ActiveEffect[];
    // Loot table - what parts can be harvested
    lootTable: {
        torso: TorsoBodyPart;
        head: HeadBodyPart;
        arm: LimbBodyPart;
        leg: LimbBodyPart;
        tail: LimbBodyPart;
    };
}

// ================================
// Combat State
// ================================

export type CombatPhase =
    | 'player_turn'
    | 'enemy_turn'
    | 'resolution'
    | 'victory'
    | 'defeat';

export interface CombatState {
    phase: CombatPhase;
    turn: number;

    // Player state
    playerCreature: PlayerCreature;
    playerAp: number;
    playerMaxAp: number;
    playerAttackQueue: SelectedAttack[];

    // Enemy state
    wildCreature: WildCreature;
    enemyAp: number;
    enemyAttackQueue: Attack[];

    // Initiative System
    initiativeQueue: InitiativeEntry[];
    currentInitiativeIndex: number;

    // Combat log
    log: CombatLogEntry[];
}

export interface InitiativeEntry {
    actorId: 'player' | 'enemy';
    speed: number;
    attack: SelectedAttack | Attack;
}

export interface CombatLogEntry {
    turn: number;
    message: string;
    type: 'attack' | 'effect' | 'heal' | 'info';
}

// ================================
// Game State
// ================================

export type GameScreen =
    | 'auth'
    | 'laboratory'
    | 'biome_select'
    | 'creature_select'
    | 'combat'
    | 'victory'
    | 'defeat';

export interface FreezerSlot {
    part: BodyPart | null;
}

export interface GameState {
    currentScreen: GameScreen;
    playerCreature: PlayerCreature;
    freezer: [FreezerSlot, FreezerSlot, FreezerSlot];
    inventory: BodyPart[];
    selectedBiome: Biome | null;
    currentCombat: CombatState | null;
    isDead: boolean;  // True if creature only has head + torso
}

// ================================
// Player (Firestore Document)
