export interface PlayerStats {
    battlesWon: number;
    battlesLost: number;
    totalPartsHarvested: number;
    deaths: number;
}

export interface PlayerDocument {
    odayId: string;
    email: string;
    displayName: string | null;
    creature: CreatureSlots;
    freezer: [BodyPart | null, BodyPart | null, BodyPart | null];
    inventory: BodyPart[];
    stats: PlayerStats;
    createdAt: Date;
    updatedAt: Date;
}

